-- RF-102 source package 1.0.0; database revision 1.
-- Run ONLY this file in the existing project's SQL Editor as postgres.
-- Imports an unpublished draft. No release, assignment, schema or scoring changes.
-- An identical rerun is a no-op, including after publication/assignment.
-- Different content under these identifiers aborts instead of overwriting records.
begin;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "b24247d7-0237-51ca-9f36-82037a9cc61d", "slug": "rf-102-retail-terms-and-hardware-vocabulary", "version": 1, "title": "Retail Terms & Hardware Vocabulary", "description": "Learn the words used in a hardware store. Use them to find products, understand daily tasks, and communicate clearly with customers and coworkers.", "category": "Retail Foundations", "passing_percent": 80}, "lessons": [{"id": "0ab673a6-d189-5fb3-8d65-b55d654d39c9", "position": 1, "title": "Speaking the Language of the Store", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "New employees hear many new words on their first shift. Clear terms help the team avoid mistakes. They also help customers feel understood."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Everyday retail terms"}, {"type": "paragraph", "text": "A department is a group of related products. Paint and plumbing are examples. An aisle is a walkway between shelves. A bay is one section of shelving. A bin is a container or small storage location. A display presents products for customers to see."}, {"type": "heading", "text": "How products move"}, {"type": "paragraph", "text": "Receiving means checking products delivered to the store. Stocking means placing products in their assigned locations. Replenishment means adding more products to a shelf or display. A return is merchandise brought back by a customer under the store’s return policy."}, {"type": "heading", "text": "Store paperwork and labels"}, {"type": "paragraph", "text": "A price tag shows a selling price. A shelf label identifies a product and may show its price. A receipt records a sale. A purchase order is a business record used to request products from a supplier. The exact forms vary by store."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A coworker says, “Please replenish the fastener bins in bay three.” The employee finds the correct shelving section and adds the right products to the assigned bins."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask a coworker to show you the store’s aisle, bay, and bin labels."}, {"type": "bullet", "text": "Repeat an unfamiliar instruction in your own words."}, {"type": "bullet", "text": "Check product labels before stocking."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating an aisle number and a bay number as the same thing. Ask how your store labels each area."}, {"type": "bullet", "text": "Assuming every store uses the same terms. Learn the terms used by your team."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or experienced coworker when a location code is unclear. Do not move merchandise based on a guess."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask a coworker to show you the store’s aisle, bay, and bin labels."}, {"type": "bullet", "text": "Repeat an unfamiliar instruction in your own words."}, {"type": "bullet", "text": "Ask a manager or experienced coworker when a location code is unclear."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P01"}, {"type": "paragraph", "text": "Question: A coworker asks you to replenish a display. What does replenish mean?"}, {"type": "bullet", "text": "A. Remove the display."}, {"type": "bullet", "text": "B. Add products to replace what has sold."}, {"type": "bullet", "text": "C. Change all product prices."}, {"type": "bullet", "text": "D. Process a customer return."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Replenish means add more merchandise to a shelf or display. It does not mean change prices or process returns."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "62c52ead-82e8-5075-8f57-082e7135ef26", "position": 2, "title": "Inventory Words You Will Hear", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Inventory words appear in conversations, labels, and store systems. You need to understand them before you can answer stock questions."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Item identifiers"}, {"type": "paragraph", "text": "A SKU is a stock keeping unit. It is an identifier a business uses to track an item. A UPC is a Universal Product Code. It is commonly shown as a barcode number on retail packaging. A store SKU and a UPC may be different. Some products have more than one barcode or packaging option."}, {"type": "heading", "text": "Stock and availability"}, {"type": "paragraph", "text": "On-hand quantity is the number recorded in the inventory system. Available quantity may account for reserved or committed stock. Stores calculate these values in different ways. Out of stock means the item is not currently available for sale at that location. Backorder means an item has been ordered but is waiting for supply. Not every store uses backorders."}, {"type": "heading", "text": "Ordering terms"}, {"type": "paragraph", "text": "A special order is a product ordered for a specific customer request. A lead time is the expected time between ordering and receiving an item. An inventory count checks the actual number of items. An inventory adjustment corrects a recorded quantity after the store verifies a difference."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "The system shows two boxes of screws on hand. The shelf is empty. An employee checks approved storage locations and asks receiving for help. They do not promise the customer that two boxes are ready to buy."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use “the system shows” when describing an unverified quantity."}, {"type": "bullet", "text": "Check approved locations before confirming availability."}, {"type": "bullet", "text": "Explain that special-order timing is an estimate until the store confirms it."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Confusing SKU with UPC. Check the field label in the system."}, {"type": "bullet", "text": "Treating on-hand quantity as proof that an item is on the shelf. Verify the item."}, {"type": "bullet", "text": "Promising an arrival date from an unconfirmed lead time."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask an inventory lead or manager about quantity differences, reserved stock, and order status. Follow the store’s process for adjustments."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Use “the system shows” when describing an unverified quantity."}, {"type": "bullet", "text": "Check approved locations before confirming availability."}, {"type": "bullet", "text": "Ask an inventory lead or manager about quantity differences, reserved stock, and order status."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P02"}, {"type": "paragraph", "text": "Question: A customer asks for an item. Your system shows four on hand, but the shelf is empty. What should you say?"}, {"type": "bullet", "text": "A. “We have four. They are ready for you.”"}, {"type": "bullet", "text": "B. “We are sold out forever.”"}, {"type": "bullet", "text": "C. “The system shows four. Let me verify where they are.”"}, {"type": "bullet", "text": "D. “The UPC must be wrong.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: On-hand quantity is a system record. Verify the actual stock before making a promise."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "27618e2f-870f-5cc5-9f4a-a4db8ddbd1c6", "position": 3, "title": "Product Names, Sizes, and Units", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Hardware products often look alike. Small differences in size or material can change how a product works. Reading the label is an important skill."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Common product families"}, {"type": "paragraph", "text": "A fastener joins materials. Screws, nails, nuts, and bolts are fasteners. A fitting connects parts of a system. Plumbing fittings are one example. A consumable is used up during work. Sandpaper and drill bits may need regular replacement. A hand tool uses human effort. A power tool uses a motor or another power source."}, {"type": "heading", "text": "Measurements and labels"}, {"type": "paragraph", "text": "Length, width, and diameter describe different dimensions. Diameter measures across a circle through its center. Gauge is a size designation used for some products. Its meaning depends on the product category. A thread is the spiral ridge on a screw or bolt. A thread size helps identify a matching fastener. The numbers and units on the package matter."}, {"type": "heading", "text": "Units and package counts"}, {"type": "paragraph", "text": "Stores sell products by each, pair, pack, foot, gallon, or other units. A price per each is not the same as a price per pack. Nominal size is a common name for a material size. It may differ from the actual measured size. Lumber is one example. Check the label and product specifications."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “a half-inch bolt.” The employee asks for the old bolt or package. They check diameter, length, thread information, and grade or strength markings as needed. They do not choose a bolt based on length alone."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Read the full product label."}, {"type": "bullet", "text": "Confirm the unit of sale before quoting a price."}, {"type": "bullet", "text": "Ask for the old part, package, or a clear photo when available."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming two similar-looking fasteners are interchangeable. Check the full specifications."}, {"type": "bullet", "text": "Confusing diameter with length. Identify each measurement."}, {"type": "bullet", "text": "Assuming nominal and actual lumber sizes are equal. Verify the dimensions."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a knowledgeable coworker or consult manufacturer specifications when strength, compatibility, load, electrical ratings, or other safety factors matter. Refer installation decisions to a qualified professional when appropriate."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Read the full product label."}, {"type": "bullet", "text": "Confirm the unit of sale before quoting a price."}, {"type": "bullet", "text": "Ask a knowledgeable coworker or consult manufacturer specifications when strength, compatibility, load, electrical ratings, or other safety factors matter."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P03"}, {"type": "paragraph", "text": "Question: A customer asks for a replacement bolt. Which detail is useful to confirm?"}, {"type": "bullet", "text": "A. Only the color of the shelf label."}, {"type": "bullet", "text": "B. Only the price."}, {"type": "bullet", "text": "C. Only the aisle number."}, {"type": "bullet", "text": "D. The diameter, length, and thread information."}, {"type": "paragraph", "text": "Answer: D"}, {"type": "paragraph", "text": "Explanation: Fasteners can differ in diameter, length, and thread. Matching these details is more useful than matching appearance alone."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "bcd656c7-9600-58b9-bc2c-81deee52f83e", "position": 4, "title": "Department Vocabulary", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers may use everyday words instead of product names. Department vocabulary helps you ask better questions and find the right team member."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Paint and decorating"}, {"type": "paragraph", "text": "Primer prepares a surface for a coating. Sheen describes how shiny a paint finish looks. Roller cover is the sleeve that holds paint on a roller frame. Caulk fills certain gaps or joints. Products have different uses. Read the label."}, {"type": "heading", "text": "Plumbing and electrical"}, {"type": "paragraph", "text": "A shutoff valve controls water flow. A supply line carries water to a fixture. A coupling joins two compatible pipe or tubing sections. An outlet is a place to connect electrical equipment. A breaker is a protective device in an electrical circuit. Employees should not diagnose electrical hazards or direct unqualified work."}, {"type": "heading", "text": "Lawn, garden, and tools"}, {"type": "paragraph", "text": "Mulch covers soil. Potting mix is a growing medium for containers. Trimmer line is cutting line used by certain string trimmers. A driver bit turns compatible screws. A drill bit makes holes in suitable material. Check tool and accessory compatibility before recommending a product."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “the string for my weed eater.” The employee recognizes that the customer may mean trimmer line. They ask for the model or the old package before checking compatible sizes."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Translate the customer’s everyday words into possible product terms."}, {"type": "bullet", "text": "Ask for a model number when fit or compatibility matters."}, {"type": "bullet", "text": "Direct the customer to the right department or coworker."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming all products with similar names have the same purpose. Read labels."}, {"type": "bullet", "text": "Treating a familiar brand name as an exact product description. Ask for details."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a department specialist or consult official product instructions for chemical use, electrical work, plumbing repairs, and equipment compatibility. Do not provide unverified safety advice."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Translate the customer’s everyday words into possible product terms."}, {"type": "bullet", "text": "Ask for a model number when fit or compatibility matters."}, {"type": "bullet", "text": "Ask a department specialist or consult official product instructions for chemical use, electrical work, plumbing repairs, and equipment compatibility."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P04"}, {"type": "paragraph", "text": "Question: A customer asks for “string for my weed eater.” What product term may help you begin the search?"}, {"type": "bullet", "text": "A. Roller cover."}, {"type": "bullet", "text": "B. Trimmer line."}, {"type": "bullet", "text": "C. Supply line."}, {"type": "bullet", "text": "D. Caulk."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Trimmer line is a common product name for the cutting line used by certain string trimmers. Confirm the model and compatible line size."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}, {"id": "5354490f-656e-5cce-b202-ecfc6c7ca65f", "position": 5, "title": "Clear Communication and Smart Questions", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Knowing a term is only part of the job. Clear communication helps coworkers act on the right information. It also helps customers avoid buying the wrong item."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Be specific"}, {"type": "paragraph", "text": "Instead of “We need more of those,” say “The one-inch paint brushes are low on the shelf in aisle four.” Instead of “The order is here,” say “The system shows the special order as received. I will verify it before contacting the customer.”"}, {"type": "heading", "text": "Use a simple question pattern"}, {"type": "paragraph", "text": "Ask what the customer needs to do. Ask where the product will be used. Ask which size, model, or material is involved. Ask whether they have the old part, package, or instructions. One clear question is better than several guesses."}, {"type": "heading", "text": "Know the limits of a term"}, {"type": "paragraph", "text": "Words like universal, standard, and heavy-duty may appear on packages. They do not prove that a product fits every project. Read the manufacturer’s specifications. If a term is unclear, say what you know and what you still need to check."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says, “I need a universal blade for this saw.” The employee asks for the saw model and the type of work. They check the blade specifications and seek help before recommending a product."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use exact product names and location details when possible."}, {"type": "bullet", "text": "Tell customers when a detail still needs verification."}, {"type": "bullet", "text": "Pass clear notes to the next employee."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Using vague words like “that one” without a product description. Name the item."}, {"type": "bullet", "text": "Assuming “universal” means guaranteed compatibility. Check the specifications."}, {"type": "bullet", "text": "Pretending to understand an unfamiliar term. Ask for clarification."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or specialist when a product label, model number, or safety claim is unclear. Refer regulated work to a qualified professional as appropriate."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Use exact product names and location details when possible."}, {"type": "bullet", "text": "Tell customers when a detail still needs verification."}, {"type": "bullet", "text": "Ask a manager or specialist when a product label, model number, or safety claim is unclear."}, {"type": "heading", "text": "Unscored lesson practice — RF-102-P05"}, {"type": "paragraph", "text": "Question: A customer asks for a “universal” saw blade. What is the best first step?"}, {"type": "bullet", "text": "A. Promise that any blade marked universal will fit."}, {"type": "bullet", "text": "B. Ask for the saw model and check blade compatibility."}, {"type": "bullet", "text": "C. Pick the least expensive blade."}, {"type": "bullet", "text": "D. Tell the customer all blades work the same way."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Marketing terms do not replace compatibility checks. Confirm the saw model and blade specifications."}, {"type": "paragraph", "text": "Scoring: Unscored. The answer and explanation appear after the question."}]}], "questions": [{"id": "4b8c29ab-2084-577d-8a25-590242a2aeee", "position": 1, "prompt": "A coworker asks you to find a product by SKU. What should you look for?", "options": ["The store’s item identifier.", "The customer’s receipt number.", "The aisle cleaning schedule.", "The supplier’s phone number."], "correct_option": 0, "explanation": "A SKU is an identifier used by the store to track an item. It is not a receipt or a phone number."}, {"id": "6d3bb220-629f-5b0b-bbcd-2d3946ce3a39", "position": 2, "prompt": "A customer needs a replacement screw. Which information helps you find a match?", "options": ["The brand of the shopping basket.", "The shelf color and price alone.", "The screw’s size and thread information.", "The day the customer bought the old screw."], "correct_option": 2, "explanation": "A replacement screw must match important dimensions and thread details. Appearance and price do not confirm a fit."}, {"id": "cdc0ae11-69f4-5c6f-94a2-5ac0a5eae4ae", "position": 3, "prompt": "A customer asks for “the string for my weed eater.” Which product should you ask about?", "options": ["A paint roller cover.", "Trimmer line.", "Electrical supply wire.", "Plumbing coupling."], "correct_option": 1, "explanation": "Trimmer line is the product name that may match the customer’s description. Check the equipment model and compatible size."}, {"id": "76cdf837-79bd-524d-8c1c-b741c81c3237", "position": 4, "prompt": "Which message gives a coworker the clearest stock update?", "options": ["“Those things are gone.”", "“We need stuff over there.”", "“The item is probably somewhere.”", "“The two-inch paint brushes are low in aisle four.”"], "correct_option": 3, "explanation": "The clearest message names the item and location. Vague descriptions can cause delays and mistakes."}, {"id": "1246caa2-cb92-545f-8d62-13c9b7523d14", "position": 5, "prompt": "A customer asks whether a blade labeled “universal” fits their saw. What should you do?", "options": ["Say it fits every saw because of the label.", "Check the saw model and blade specifications before recommending it.", "Choose any blade with the same package color.", "Tell the customer that all blades have the same mounting system."], "correct_option": 1, "explanation": "A word like “universal” does not prove compatibility. Check manufacturer specifications and ask for help when needed."}], "catalog": {"course_code": "RF-102", "skill_level": "foundations", "topics": ["Retail vocabulary", "Inventory", "Product knowledge"], "keywords": ["SKU", "UPC", "stock keeping unit", "barcode", "nominal size", "fasteners", "trimmer line"], "learning_paths": ["New Retail Employee"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'RF-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'RF-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'RF-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'RF-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
commit;
select slug,title,published,
 (select count(*) from public.training_lessons where course_id=c.id) as lessons,
 (select count(*) from public.training_questions where course_id=c.id) as quiz_questions
from public.training_courses c where id='b24247d7-0237-51ca-9f36-82037a9cc61d';
